#include <print>

bool is_prime(int n);                  // 声明：预告片，注意分号

int main() {
    for (int n : {2, 9, 17, 21}) {
        std::println("{} {}", n, is_prime(n) ? "是素数" : "不是");
    }
    return 0;
}

bool is_prime(int n) {                 // 定义：正片放在 main 后面
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i)
        if (n % i == 0) return false;
    return true;
}

